#include <iostream>

#define NAME_SIZE 32

using std::cout;
using std::endl;

struct Student
{
    char szName[NAME_SIZE];
    int iKorean;
    int iMath;
    int iEnglish;
    int iTotal;
    float fAverage;
};

int main()
{
    Student tStudent = {};

    strcpy_s(tStudent.szName, "찬연");

    Student* pStudent = &tStudent;

    pStudent->iKorean = 90;
    pStudent->iMath = 85;
    pStudent->iEnglish = 80;

    pStudent->iTotal = pStudent->iKorean + pStudent->iMath + pStudent->iEnglish;
    pStudent->fAverage = (float)pStudent->iTotal / 3;

    cout << "이름: " << pStudent->szName << endl;
    cout << "총점: " << pStudent->iTotal << endl;
    cout << "평균: " << pStudent->fAverage << endl;

    return 0;
}

