#include <iostream>

using std::cout;
using std::endl;

struct Monster
{
    char szName[32];
    int iHP;
    int iAttack;
};

int main()
{
    Monster arr[3] =
    {
        { "슬라임", 50, 5 },
        { "고블린", 80, 10 },
        { "드래곤", 300, 40 }
    };

    Monster* p = arr;

    for (int i = 0; i < 3; ++i)
    {
        (p + i)->iHP -= 20;
        cout << (p + i)->szName << " HP: " << (p + i)->iHP << endl;
    }

    Monster* pWeakest = arr;

    for (int i = 1; i < 3; ++i)
    {
        if ((p + i)->iHP < pWeakest->iHP)
        {
            pWeakest = p + i;
        }
    }

    cout << "가장 약한 몬스터: " << pWeakest->szName << " (HP " << pWeakest->iHP << ")" << endl;

    return 0;
}
